mkdir -p /tmp/bot-check && cat > /tmp/bot-check/check.mjs <<'EOF'
import assert from "node:assert/strict";
import { decideWhatsApp } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/courier-g5-1/bot.mjs";

const T0 = 1767272400; // webhook timestamp (seconds)
const now = new Date((T0 + 3600) * 1000); // 1 hour after inbound
const at = (sec) => new Date(sec * 1000);
const c = (over = {}) => ({ optedIn: true, lastInboundTimestamp: String(T0), ...over });
const text = (contact) => ({ type: "text", contact });
const tpl = (contact) => ({ type: "template", contact });
const ok = { allowed: true, reason: null };
const no = (reason) => ({ allowed: false, reason });

const cases = [
  ["text inside window", text(c()), now, ok],
  ["text 23h59m59s after inbound", text(c()), at(T0 + 86399), ok],
  ["text exactly 24h after inbound (closed)", text(c()), at(T0 + 86400), no("outside_customer_service_window")],
  ["text 25h after inbound", text(c()), at(T0 + 90000), no("outside_customer_service_window")],
  ["text never wrote to us", text(c({ lastInboundTimestamp: null })), now, no("outside_customer_service_window")],
  ["text not opted in", text(c({ optedIn: false })), now, no("not_opted_in")],
  ["text optedIn truthy string", text(c({ optedIn: "true" })), now, no("not_opted_in")],
  ["template inside window", tpl(c()), now, ok],
  ["template outside window, opted in", tpl(c({ lastInboundTimestamp: null })), now, ok],
  ["template 30 days after inbound", tpl(c()), at(T0 + 30 * 86400), ok],
  ["template not opted in", tpl(c({ optedIn: false, lastInboundTimestamp: null })), now, no("not_opted_in")],
  ["unknown type", { type: "image", contact: c() }, now, no("unsupported_message_type")],
  ["missing type", { contact: c() }, now, no("unsupported_message_type")],
  ["missing contact", { type: "text" }, now, no("missing_contact")],
  ["timestamp as number (not Meta format)", text(c({ lastInboundTimestamp: T0 })), now, no("invalid_inbound_timestamp")],
  ["timestamp in milliseconds", text(c({ lastInboundTimestamp: String(T0 * 1000) })), now, no("invalid_inbound_timestamp")],
  ["timestamp with decimals", text(c({ lastInboundTimestamp: "1767272400.5" })), now, no("invalid_inbound_timestamp")],
  ["timestamp missing", text({ optedIn: true }), now, no("invalid_inbound_timestamp")],
  ["timestamp 10 min in future", text(c({ lastInboundTimestamp: String(T0 + 600) })), at(T0 - 1), no("invalid_inbound_timestamp")],
  ["timestamp 1 min ahead (clock skew, allowed)", text(c({ lastInboundTimestamp: String(T0 + 60) })), at(T0), ok],
  ["template with bad timestamp still allowed", tpl(c({ lastInboundTimestamp: "garbage" })), now, ok],
];

let failed = 0;
for (const [name, msg, when, want] of cases) {
  try {
    assert.deepStrictEqual(decideWhatsApp(msg, when), want);
    console.log("PASS", name);
  } catch (e) {
    failed++;
    console.log("FAIL", name, JSON.stringify(decideWhatsApp(msg, when)));
  }
}
assert.throws(() => decideWhatsApp(text(c()), new Date("nope")), TypeError);
assert.throws(() => decideWhatsApp(text(c()), "2026-01-01"), TypeError);
console.log("PASS invalid now throws TypeError");
console.log(failed === 0 ? `ALL ${cases.length} CASES PASS` : `${failed} FAILED`);
process.exitCode = failed ? 1 : 0;
EOF
cd /tmp/bot-check && node check.mjs
